(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin((x+wx1)*0.035+t*0.5)*8+Math.cos((y+wy1)*0.03-t*0.4)*6;
  const wy2 = Math.cos((y+wy1)*0.03-t*0.45)*8+Math.sin((x+wx1)*0.028+t*0.55)*6;
  const sx = x+wx1+wx2, sy = y+wy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [60+Math.sin(t*0.45+3)*70,40+Math.cos(t*0.65+1)*50,0.11,2.1,0.85],
    [420+Math.cos(t*0.55+2)*60,200+Math.sin(t*0.75+4)*40,0.13,1.8,1.05]
  ];
  let aS=0,iS=0,pulse=0,cross=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    pulse+=Math.sin(d*f*0.3-t*sp*0.4)*Math.exp(-d*0.005)*amp;
    cross+=Math.sin(d*f*1.2-t*sp*0.8+0.7)*Math.sin(d*f*0.5+t*sp*0.3);
  }
  const n=src.length,act=aS/n,inh=iS/n,pls=pulse/n,crs=cross/n;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.07+sy*0.05-t*0.6)*0.5+Math.sin(sx*0.015-sy*0.02+t*0.4)*0.7)/3.2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.08-ang*5+t*0.9)*0.5+Math.sin(dist*0.025+ang*2-t*2.1)*0.4)*0.3;
  const clx=sx*0.12,cly=sy*0.12,ci=clx|0,cj=cly|0;
  let minD=99;
  for(let di=-1;di<=1;di++)for(let dj=-1;dj<=1;dj++){
    const nx=ci+di,ny=cj+dj;
    const px=nx+Math.sin(nx*1.7+ny*2.3+t*0.3)*0.4+Math.cos(nx*3.1+ny*0.7+t*0.2)*0.3;
    const py=ny+Math.cos(nx*2.1+ny*1.3+t*0.25)*0.4+Math.sin(nx*0.9+ny*2.7+t*0.35)*0.3;
    const d=Math.sqrt((clx-px)**2+(cly-py)**2);
    if(d<minD)minD=d;
  }
  const cell=Math.tanh((minD-0.5)*6)*0.35;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+pls*0.4+crs*0.2)*2.0);
  const blend=reaction*0.6+cell*0.25+pls*0.15,v=blend*0.5+0.5;
  const pal=[[10,12,48],[22,48,88],[32,90,115],[48,142,125],[130,178,105],[205,190,75],[225,145,60],[195,85,55],[135,40,50],[65,18,45],[28,12,40],[10,12,48]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+Math.abs(pls)*0.1;
  const edge=Math.abs(reaction)>0.65?1.12:Math.abs(crs)>0.5?1.05:1.0;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
